+void grouped_diagonal_rankk_cuda(
+        torch::Tensor panel, torch::Tensor output) {
+    TORCH_CHECK(panel.is_cuda() && output.is_cuda(), "CUDA tensors required");
+    TORCH_CHECK(panel.scalar_type() == torch::kFloat32
+                && output.scalar_type() == torch::kFloat32,
+                "FP32 tensors required");
+    TORCH_CHECK(panel.dim() == 3 && output.dim() == 3
+                && panel.size(0) == output.size(0)
+                && panel.size(1) == 256
+                && panel.size(2) == output.size(1)
+                && output.size(1) == output.size(2)
+                && panel.stride(2) == 1 && output.stride(2) == 1,
+                "compatible grouped panel and trailing output required");
+    const int trailing = static_cast<int>(output.size(1));
+    TORCH_CHECK((trailing % 256) == 0,
+                "trailing dimension must be 256 aligned");
+    const int macro_count = trailing / 256;
+    grouped_diagonal_rankk_kernel<<<
+        dim3(16, 16, output.size(0) * macro_count), 32, 0,
+        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()
+    >>>(
+        panel.data_ptr<float>(),
+        output.data_ptr<float>(),
+        macro_count,
+        static_cast<int>(panel.stride(1)),
+        static_cast<int>(output.stride(1)),
+        panel.stride(0),
+        output.stride(0)
+    );
+    C10_CUDA_KERNEL_LAUNCH_CHECK();
+}
