def _grouped_mathdx_cholesky(
    data: torch.Tensor,
    output: torch.Tensor,
    pointers: torch.Tensor,
    output_view,
) -> torch.Tensor:
    n = output.shape[-1]
    block = _G2048_N
    key = id(output)
    stage_entry = _g2048_stage_cache.get(key)
    if stage_entry is None or stage_entry[0] is not output:
        stages = []
        for panel_index, panel_origin in enumerate(range(0, n, block)):
            stop = panel_origin + block
            launch_args = (
                np.int64(n),
                np.int64(n * n),
                np.int64(panel_origin),
            )
            if stop == n:
                stages.append((launch_args, panel_index, None))
                continue
            panel = output[:, panel_origin:stop, stop:]
            trailing_output = output[:, stop:, stop:]
            panel_pointer = cute_runtime.make_ptr(
                cutlass.Float32,
                panel.data_ptr(),
                cute.AddressSpace.gmem,
                assumed_align=16,
            )
            output_pointer = cute_runtime.make_ptr(
                cutlass.Float32,
                trailing_output.data_ptr(),
                cute.AddressSpace.gmem,
                assumed_align=16,
            )
            rankk_stage = (
                n - stop,
                panel,
                trailing_output,
                panel_pointer,
                output_pointer,
                (
                    cutlass.Int32(n - stop),
                    cutlass.Int32(block),
                    cutlass.Int32(output.shape[0]),
                    cutlass.Int32(output.stride(0)),
                    cutlass.Int32(output.stride(1)),
                    cutlass.Int32(output.stride(0)),
                ),
            )
            stages.append((launch_args, panel_index, rankk_stage))
        stage_entry = (output, tuple(stages))
        _g2048_stage_cache[key] = stage_entry
    _ext.grouped_prepare_(data, output)
    stages = stage_entry[1]
    launcher = _g2048_launcher_for_current_queue(
        output_view,
        output_view,
        output.shape[0],
        stages[0][0],
    )
    for launch_args, panel_index, rankk_stage in stages:
        launcher(
            output_view,
            output_view,
            *launch_args,
        )
        _ext.grouped_panel_update_(
            output, pointers, block, panel_index
        )
        if rankk_stage is not None:
            if rankk_stage[0] > block:
                _g2048_triangular_rankk_(
                    rankk_stage[3],
                    rankk_stage[4],
                    rankk_stage[5],
                )
            _ext.grouped_diagonal_rankk_cuda(
                rankk_stage[1], rankk_stage[2]
            )
    return _ext.grouped_finish_masked(output)


